from (values
  (1, 0, 'A JavaScript runtime based on the V8 engine that runs outside the browser, event-driven and with non-blocking I/O.'),
  (1, 1, 'A front-end framework for building user interfaces in the browser, based on the SpiderMonkey engine, that renders components and manages client-side routing.'),
  (1, 2, 'A multi-threaded Java runtime that executes JavaScript through the JVM, creating one blocking thread per request to handle I/O operations in parallel.'),
  (1, 3, 'A JavaScript framework for building user interfaces in the browser.'),
  (2, 0, 'JavaScript code runs on a main thread, but I/O is delegated to libuv (thread pool and OS), allowing concurrency. For CPU-intensive work, worker threads are used.'),
  (2, 1, 'No. Every incoming request is automatically assigned to its own operating system thread, so JavaScript code always runs in parallel across all CPU cores without any extra configuration.'),
  (2, 2, 'Yes, and because of that it cannot perform any concurrent operation: each I/O call blocks the whole process until it completes, which is why worker threads were removed.'),
  (2, 3, 'No, every request automatically runs on its own dedicated thread.'),
