from (values
  (1, 0, 'Ambiente de execução JavaScript baseado no motor V8 que roda fora do navegador, orientado a eventos e com I/O não bloqueante.'),
  (1, 1, 'Framework front-end para construir interfaces no navegador, baseado no motor SpiderMonkey, que renderiza componentes e gerencia roteamento no cliente.'),
  (1, 2, 'Runtime Java multi-thread que executa JavaScript pela JVM, criando uma thread bloqueante por requisição para tratar operações de I/O em paralelo.'),
  (1, 3, 'Framework JavaScript para construir interfaces no navegador.'),
  (2, 0, 'O código JavaScript roda em uma thread principal, mas I/O é delegado ao libuv (thread pool e SO), permitindo concorrência. Para CPU intensiva usam-se worker threads.'),
