select q.id, v.source_index, v.body, v.source_index = 0
from (values
  (1, 0, 'An interpreted, dynamic, multi-paradigm programming language used in the browser, on the server (Node.js) and in many other environments.'),
  (1, 1, 'A compiled, statically typed language derived from Java that runs only inside the browser''s sandbox and cannot be used on servers or other environments.'),
  (1, 2, 'A markup language used to structure web pages, similar to HTML.'),
