  (2, 0, 'string, number, boolean, null, undefined, symbol and bigint.'),
  (2, 1, 'string, number, boolean, object, array and function, since arrays and functions are stored by value like the other primitives.'),
  (2, 2, 'string, int, float, char, boolean and null.'),
  (2, 3, 'string, number, boolean, undefined, Date and RegExp.'),
  (3, 0, 'var is function-scoped and hoisted with undefined; let and const are block-scoped; const doesn''t allow reassignment.'),
  (3, 1, 'var and let are block-scoped and can be reassigned; const is function-scoped and makes objects deeply immutable, so their properties cannot change either.'),
  (3, 2, 'var and let are block-scoped; const is function-scoped and fully immutable.'),
  (3, 3, 'All three are block-scoped; const prevents mutation of objects.'),
