  (6, 2, '== compares object references and === compares the contents of objects deeply, so two objects with the same keys are === equal.'),
  (6, 3, '=== compares with type coercion; == compares value and type without coercion.'),
  (7, 0, 'false, 0, -0, 0n, "", null, undefined and NaN. Everything else is truthy.'),
