  (9, 2, 'An alias for null used in numeric contexts; you check for it with value === NaN, which returns true for invalid results.'),
  (9, 3, 'An error thrown when dividing by zero.'),
  (10, 0, 'A reusable block of code that can receive parameters and return a value; in JS, functions are first-class values.'),
  (10, 1, 'A special object that can only be called once and cannot be stored in variables or passed as an argument to other functions.'),
  (10, 2, 'A block of code that always runs automatically when the page loads.'),
  (10, 3, 'A statement that declares a class with methods.'),
  (11, 0, 'A declaration is fully hoisted and can be called before it is defined; an expression only exists after assignment.'),
  (11, 1, 'A function expression is fully hoisted and can be called before it appears, while a declaration only exists after the line where it is defined runs.'),
  (11, 2, 'A declaration cannot receive parameters or return values, while an expression can; otherwise they behave the same in every scope.'),
  (11, 3, 'There is no difference other than syntax.'),
