  (12, 1, 'A short syntax ((a, b) => a + b) that creates its own this bound to the caller and its own arguments object, and can be used as a constructor with new.'),
  (12, 2, 'Functions that run asynchronously by default.'),
  (12, 3, 'Functions that can only return objects.'),
