  (95, 1, 'Templates HTML marcados com atributos data-tag que o navegador preenche com valores de objetos JavaScript.'),
  (95, 2, 'Template literals que só podem conter tags HTML e são escapados automaticamente na interpolação.'),
  (95, 3, 'Tags do Git aplicadas a arquivos de template.'),
  (96, 0, 'Proposta padronizada para anotar classes e membros com @; já é suportada por transpiladores e vem sendo implementada nos motores.'),
  (96, 1, 'Recurso nativo antigo suportado por todo navegador desde o ES2015 e usado amplamente sem transpilador.'),
  (96, 2, 'Recurso exclusivo do TypeScript que nunca fará parte do JavaScript, então sempre exige o tsc.'),
  (96, 3, 'Recurso de CSS para decorar textos.'),
  (97, 0, 'O dinâmico carrega módulos sob demanda e retorna Promise, permitindo code splitting; o estático é resolvido antes da execução.'),
  (97, 1, 'O import() dinâmico é síncrono e retorna o módulo diretamente, então pode ser usado em qualquer lugar sem await.'),
  (97, 2, 'O estático carrega sob demanda; o dinâmico é resolvido antes da execução.'),
  (97, 3, 'O dinâmico só funciona no Node; o estático só nos navegadores.'),
  (98, 0, 'Permite usar await no topo de módulos ES, sem envolver em função async.'),
  (98, 1, 'Permite await no topo de arquivos CommonJS carregados com require, bloqueando quem importa até resolver.'),
  (98, 2, 'Torna toda função declarada no módulo async automaticamente, permitindo await em qualquer lugar.'),
  (98, 3, 'Permite await em qualquer arquivo CommonJS.'),
  (99, 0, 'Operadores convertem para primitivos: [] + {} resulta em "[object Object]" e [] == ![] é true, pois ambos viram 0. Evite coerção implícita.'),
  (99, 1, '[] + {} resulta em 0 porque os dois operandos viram números, e [] == ![] é false porque um array nunca é igual a um boolean.'),
  (99, 2, '[] + {} retorna "{}" concatenando o JSON do objeto, e [] == ![] é false porque os dois valores têm tipos diferentes.'),
  (99, 3, '[] + {} resulta em 0 e [] == ![] é false.'),
