  (100, 1, 'Ter um único desenvolvedor sênior escrevendo e aprovando todo o código para manter o estilo consistente sem ferramentas.'),
  (100, 2, 'Pular testes para entregar mais rápido e confiar nos usuários para reportar bugs em produção, corrigindo com hotfixes.'),
  (100, 3, 'Minificar o código para dificultar alterações.')
) as v (source_id, source_index, body)
join public.questions q on q.quiz_id = 'javascript' and q.language = 'pt-br' and q.source_id = v.source_id
on conflict (question_id, source_index) do update set body = excluded.body, is_correct = excluded.is_correct;

