select q.id, v.source_index, v.body, v.source_index = 0
from (values
  (1, 0, 'A full-stack React framework from Vercel that provides routing, server rendering, optimizations and API routes in one tool.'),
  (1, 1, 'A JavaScript runtime created by Google that replaces Node.js for React applications, providing its own package manager, bundler and test runner in a single binary.'),
  (1, 2, 'A client-side state management library from Vercel that replaces Redux and Context, synchronizing React state with the server through WebSockets automatically.'),
  (1, 3, 'A CSS framework from Vercel for building responsive layouts.'),
  (2, 0, 'File-based routing, SSR/SSG/ISR, image and font optimization, better SEO, automatic code splitting and an integrated backend.'),
  (2, 1, 'It removes the need for JavaScript in the browser entirely, compiling every React component into static HTML and CSS that never hydrates on the client.'),
  (2, 2, 'It replaces React''s component model with HTML templates and a built-in database, so developers no longer write JSX or call external APIs.'),
  (2, 3, 'It includes a built-in database and ORM.'),
  (3, 0, 'A modern routing system based on the app/ folder, using React Server Components, nested layouts and streaming.'),
  (3, 1, 'The classic routing system based on the pages/ folder, which uses getServerSideProps and getStaticProps for data fetching and _app.tsx for layouts.'),
  (3, 2, 'A client-only router that replaces React Router, handling navigation entirely in the browser without any server rendering or streaming.'),
  (3, 3, 'A Vercel dashboard feature for managing domains.'),
  (4, 0, 'The classic system based on the pages/ folder, with getServerSideProps and getStaticProps; still supported.'),
  (4, 1, 'The new routing system based on the app/ folder, which uses React Server Components, nested layouts and streaming with Suspense.'),
  (4, 2, 'A deprecated router that has been removed from every Next.js version since 13 and no longer works in any project.'),
  (4, 3, 'A library for paginating lists.'),
  (5, 0, 'By creating a folder in app/ with a page.tsx file; the folder name becomes the URL segment.'),
  (5, 1, 'By adding an entry with the path and component to a routes.json file at the project root, which Next.js reads at build time to generate pages.'),
  (5, 2, 'By creating a file named after the route directly inside app/, such as app/about.tsx, without needing a folder or page.tsx file.'),
  (5, 3, 'By registering the route with createRoute() in next.config.js.'),
  (6, 0, 'A component that wraps child pages and persists across navigations without re-rendering. The root layout defines <html> and <body>.'),
  (6, 1, 'A component that re-mounts on every navigation between child pages, resetting its state and re-running effects each time the URL changes.'),
  (6, 2, 'A CSS file that defines the page grid.'),
  (6, 3, 'A configuration file for responsive breakpoints.'),
  (7, 0, 'Segments in square brackets, like app/blog/[slug]/page.tsx, that capture URL parameters.'),
  (7, 1, 'Segments in curly braces, such as app/blog/{slug}/page.tsx, that capture URL parameters and pass them as props.'),
  (7, 2, 'Routes generated at runtime by calling router.add() in middleware, based on records stored in a database.'),
  (7, 3, 'Routes whose content changes randomly on each visit.'),
  (8, 0, '[...slug] captures multiple segments; [[...slug]] makes them optional.'),
  (8, 1, '[*slug] captures multiple segments and [?slug] makes them optional, following glob syntax.'),
  (8, 2, 'Routes that redirect every unknown URL back to the home page instead of showing a 404.'),
  (8, 3, '[*slug] captures multiple segments; [?slug] makes them optional.'),
  (9, 0, 'Folders in parentheses, like (marketing), that organize routes without affecting the URL.'),
  (9, 1, 'Folders in square brackets, such as [marketing], that add a dynamic prefix to every URL inside them.'),
  (9, 2, 'Folders prefixed with @, such as @marketing, that render several pages in parallel in the same layout.'),
  (9, 3, 'Groups of routes that share the same API key.'),
  (10, 0, 'next/link performs client-side navigation with automatic prefetching of visible routes.'),
  (10, 1, 'A component that always performs a full page reload to guarantee fresh data, similar to a plain <a> tag.'),
  (10, 2, 'A component for linking external stylesheets and fonts in the document head of every page.'),
  (10, 3, 'A component that creates anchor links only within the same page.'),
  (11, 0, 'With useRouter from next/navigation (router.push) or redirect() in Server Components.'),
  (11, 1, 'With window.location.href only, because Next.js does not provide any navigation API for client or server code.'),
  (11, 2, 'With useNavigate imported from react-router-dom, which Next.js bundles and configures automatically.'),
  (11, 3, 'With the navigate() function exported from next/link.'),
  (12, 0, 'next/image optimizes images automatically: resizing, modern formats (WebP/AVIF), lazy loading and layout shift prevention.'),
  (12, 1, 'A component that converts raster images into SVG at build time so they scale perfectly on every screen.'),
  (12, 2, 'A component that only accepts images from the public folder and serves them as-is, without resizing or format changes.'),
  (12, 3, 'next/image converts every raster image into SVG at build time, inlines it in the HTML and disables lazy loading, so images always render instantly and never cause layout shift on any device.'),
  (13, 0, 'It optimizes fonts (Google or local), self-hosting them on your domain and eliminating external requests and layout shift.'),
