  (96, 1, 'Prefixar segredos com NEXT_PUBLIC_, o que faz o Next.js criptografá-los antes de incluí-los no bundle do cliente.'),
  (96, 2, 'Guardar segredos na pasta public com nome de arquivo oculto.'),
  (96, 3, 'Usar ''use client'' nos arquivos que leem segredos.'),
  (97, 0, 'Metadados dinâmicos, JSON-LD, canonical, sitemaps, SSR/SSG de conteúdo, hreflang e URLs consistentes.'),
  (97, 1, 'Renderizar todo o conteúdo no cliente com JavaScript, já que buscadores executam scripts e preferem páginas dinâmicas.'),
  (97, 2, 'Usar só meta tags de keywords e esconder textos extras com palavras-chave via CSS para melhorar o ranking.'),
  (97, 3, 'Renderizar todo o conteúdo no cliente com JavaScript.'),
  (98, 0, 'Via headers() no next.config.js ou middleware: CSP, HSTS, X-Frame-Options e Referrer-Policy.'),
  (98, 1, 'O Next.js define todo cabeçalho de segurança automaticamente, e não há forma suportada de personalizar ou adicionar outros.'),
  (98, 2, 'Adicionando-os em Client Components com useEffect, que define os cabeçalhos no documento após a hidratação.'),
  (98, 3, 'O Next.js define todos os cabeçalhos automaticamente, sem configuração possível.'),
  (99, 0, 'Paginação por cursor no servidor, searchParams como fonte de verdade, infinite scroll com Client Component e virtualização.'),
  (99, 1, 'Carregar todos os registros do banco de uma vez e esconder os que estão fora da página atual com CSS.'),
  (99, 2, 'Guardar o número da página atual em uma variável global no servidor, compartilhada por toda requisição.'),
  (99, 3, 'Renderizar todos os itens em um único Server Component sem limites.'),
  (100, 0, 'Next.js para apps full-stack React com ecossistema vasto; Remix/React Router para foco em padrões web; Astro para sites de conteúdo com pouco JS.'),
  (100, 1, 'Astro para dashboards muito interativos com bastante estado no cliente, e Next.js só para blogs estáticos sem backend.'),
  (100, 2, 'Astro para dashboards muito interativos com bastante estado no cliente; Remix para sites de conteúdo sem JavaScript; Next.js só para blogs estáticos ou apps mobile em React Native.'),
  (100, 3, 'São intercambiáveis, sem trade-offs relevantes.')
) as v (source_id, source_index, body)
join public.questions q on q.quiz_id = 'nextjs' and q.language = 'pt-br' and q.source_id = v.source_id
on conflict (question_id, source_index) do update set body = excluded.body, is_correct = excluded.is_correct;

