insert into public.answer_options (question_id, source_index, body, is_correct)
select q.id, v.source_index, v.body, v.source_index = 0
from (values
  (1, 0, 'A declarative, component-based JavaScript library created by Facebook (Meta) for building user interfaces.'),
  (1, 1, 'A full-stack framework created by Google that bundles routing, a template engine and an ORM for building server-rendered web applications.'),
  (1, 2, 'An imperative DOM manipulation library created by Microsoft that replaced jQuery as the default way to update HTML pages directly.'),
  (1, 3, 'An imperative templating engine created by Microsoft that compiles HTML files into optimized JavaScript bundles.'),
  (2, 0, 'A syntax extension that lets you write HTML-like structures inside JavaScript. The compiler transforms it into React.createElement (or jsx()) calls.'),
  (2, 1, 'A templating language that the browser parses natively at runtime, converting tags into DOM nodes without requiring Babel or any compiler step.'),
  (2, 2, 'A strict superset of HTML that React sends to the server, where it is rendered into static markup and returned to the client as a string.'),
  (2, 3, 'A new programming language that replaces JavaScript in React projects and is executed directly by the browser without compilation.'),
  (3, 0, 'A reusable function (or class) that receives props and returns React elements describing part of the UI.'),
  (3, 1, 'A global singleton that stores the entire application state and is automatically shared with every page through the React runtime.'),
  (3, 2, 'An HTML file loaded at runtime and injected into the page with innerHTML, describing part of the interface as static markup.'),
  (3, 3, 'A CSS module that groups styles and is applied to DOM elements by class name.'),
  (4, 0, 'Functional components are plain functions that use Hooks for state and effects; class components use this, state and lifecycle methods. Today, functional components are the standard.'),
  (4, 1, 'Class components are plain functions that use Hooks, while functional components use this, state and lifecycle methods; classes are the modern standard.'),
  (4, 2, 'Functional components cannot hold state or effects at all; class components are the only way to manage state, and they are the current recommended standard.'),
  (4, 3, 'Class components run on the server and functional components run only in the browser; both are equally recommended today.'),
  (5, 0, 'Data passed from the parent component to the child, read-only (immutable inside the child).'),
  (5, 1, 'Data owned by the child component, which it can freely modify and send back up to the parent automatically on each render.'),
  (5, 2, 'Global variables injected into every component by React, accessible anywhere without being passed down explicitly.'),
  (5, 3, 'Global variables shared by all components in the application without needing to be passed down.'),
  (6, 0, 'Internal data of a component that changes over time and, when updated, triggers a new render.'),
  (6, 1, 'Read-only data received from the parent component that never changes during the component''s lifetime and never triggers renders.'),
  (6, 2, 'Data stored in the browser''s localStorage that React reads automatically on every render.'),
  (6, 3, 'A static configuration object defined once at build time and shared between all instances of a component.'),
  (7, 0, 'Props come from outside and are immutable for the component; state belongs to the component and is updated by it (via setState/useState).'),
  (7, 1, 'Props belong to the component and can be changed directly; state comes from the parent and is read-only.'),
  (7, 2, 'Props and state are the same thing; the names are interchangeable and only differ between class and function components.'),
  (7, 3, 'Props are used only for styling while state is used only for data fetched from APIs.'),
  (8, 0, 'An in-memory representation of the element tree. React compares versions (diffing) and applies only what changed to the real DOM.'),
  (8, 1, 'A hidden copy of the real DOM that React throws away and recreates completely on every render, replacing the entire page to stay in sync.'),
  (8, 2, 'A browser API, similar to Shadow DOM, that isolates each component''s styles and markup from the rest of the page for encapsulation.'),
  (8, 3, 'A server-side cache of rendered HTML pages that React serves instead of the real DOM to improve SEO.'),
  (9, 0, 'A Hook that declares a state variable in a functional component. It returns [value, setValue].'),
  (9, 1, 'A Hook that returns a mutable object whose .current property persists between renders without causing a new render.'),
  (9, 2, 'A Hook that reads a value from the nearest Context provider and returns it together with a dispatch function.'),
  (9, 3, 'A Hook that returns a mutable object whose .current property persists without causing re-renders.'),
  (10, 0, 'A Hook for running side effects (requests, subscriptions, DOM manipulation) after rendering, controlled by a dependency array.'),
  (10, 1, 'A Hook that runs synchronously during rendering to compute derived values before the JSX is returned, controlled by a dependency array.'),
  (10, 2, 'A Hook that memoizes an expensive calculation and recalculates it only when its dependencies change.'),
  (10, 3, 'A Hook that runs only once on the server to fetch data before the HTML is sent to the client.'),
  (11, 0, 'A list of values that, when changed, make the effect run again. An empty array runs only on mount; no array runs on every render.'),
  (11, 1, 'A list of values the effect is not allowed to read. An empty array makes the effect run on every render; omitting it runs only on mount.'),
  (11, 2, 'A list of child components that must re-render after the effect. An empty array disables the effect entirely.'),
  (11, 3, 'A list of props that are passed to the cleanup function. Omitting it makes the effect run only on unmount.'),
  (12, 0, 'With if, the ternary operator (cond ? A : B), && (cond && <A/>) or by returning null.'),
  (12, 1, 'Only with the built-in <If>, <ElseIf> and <Else> components that React exports, since JSX does not evaluate JavaScript expressions inside braces.'),
  (12, 2, 'With the v-if and v-show directives placed directly on JSX elements, which React evaluates before deciding what to render.'),
  (12, 3, 'By setting display: none through the hidden prop, since JSX does not support JavaScript expressions.'),
  (13, 0, 'Using array.map() returning elements, each with a unique and stable key.'),
  (13, 1, 'Using array.forEach() inside the JSX braces, which collects the returned elements automatically and assigns keys by position.'),
  (13, 2, 'Using the built-in <List items={...}> component, which iterates the array and generates stable keys so you never need to provide them.'),
  (13, 3, 'Using a for loop directly inside the JSX braces, with the array index as the only option for key.'),
  (14, 0, 'It helps React identify which items changed, were added or removed, optimizing reconciliation.'),
  (14, 1, 'It defines the CSS selector React uses to style each list item, so items with the same key share the same styles.'),
  (14, 2, 'It sets the order in which items are sorted before rendering, so React always displays them in ascending key order.'),
  (14, 3, 'It encrypts list items so they cannot be read from the DOM by third-party scripts.'),
  (15, 0, 'If the list is reordered, filtered or has insertions, the index changes and can cause state bugs and unnecessary renders. Prefer stable IDs.'),
  (15, 1, 'Because React throws a compile-time error whenever a number is used as a key, so indexes must always be converted to strings first.'),
  (15, 2, 'Because numeric keys are always slower to compare than strings, causing measurable slowdowns even in lists that never change order.'),
  (15, 3, 'Because indexes are recalculated by React on every render using a random seed, so the same item receives a different key each time and its DOM node is always recreated from scratch.'),
  (16, 0, '<>...</> lets you group multiple elements without adding an extra node to the DOM.'),
  (16, 1, '<>...</> renders its children inside an invisible <div> wrapper that is excluded from CSS selectors but still present in the DOM tree.'),
  (16, 2, 'Fragments split a large component into smaller files that React loads lazily on demand, reducing the initial bundle size.'),
  (16, 3, 'Fragments are partial renders that React uses to update only part of a component''s output.'),
  (17, 0, 'With camelCase props like onClick={handler}, passing a function (not a call).'),
  (17, 1, 'With lowercase HTML attributes like onclick="handler()", passing a string of code that React evaluates when the event fires.'),
  (17, 2, 'With camelCase props like onClick={handler()}, invoking the function during render so that React receives the returned value as the listener.'),
  (17, 3, 'With lowercase HTML attributes like onclick="handler()", passing a string that is evaluated.'),
  (18, 0, 'An input whose value is controlled by React state (value + onChange).'),
  (18, 1, 'An input whose value is managed by the DOM itself and read through a ref only when needed, such as on submit.'),
  (18, 2, 'A component whose rendering is controlled entirely by its parent through a shouldRender prop that React checks before each update.'),
  (18, 3, 'An input that is validated automatically by the browser using HTML attributes only.'),
  (19, 0, 'An input whose value is managed by the DOM itself and read via ref when needed.'),
  (19, 1, 'An input whose value is driven by React state through the value and onChange props on every keystroke.'),
