  (86, 3, 'Loading the full list on the server and sending it as an image.'),
  (87, 0, 'Organization by feature/domain, shared components in ui, layers for data/hooks/services and clear import boundaries.'),
  (87, 1, 'Folders organized strictly by file type (all .js in one, all .css in another), regardless of feature or domain.'),
  (87, 2, 'A single flat components folder with every file, because React''s bundler requires a flat structure to resolve imports, plus one global utils file shared by all features.'),
  (87, 3, 'One folder per developer so that teams don''t conflict.'),
  (88, 0, 'Components that work together sharing implicit state (e.g., Tabs, Tabs.List, Tabs.Panel), usually via Context.'),
  (88, 1, 'Components that inherit from a common base class and share behavior through the prototype chain.'),
  (88, 2, 'Components compiled together into a single bundle chunk (e.g., Tabs, Tabs.List, Tabs.Panel) so they always load at the same time, usually configured through webpack''s splitChunks.'),
  (88, 3, 'Components compiled together into a single bundle file.'),
  (89, 0, 'They let the consumer control or override the internal state of a reusable component, giving flexibility to design systems.'),
  (89, 1, 'They prevent consumers from changing a reusable component''s internal state, enforcing consistency in design systems.'),
  (89, 2, 'They move all component state into Redux reducers automatically so it can be inspected in DevTools.'),
  (89, 3, 'They validate props with a reducer function before rendering.'),
  (90, 0, 'Tokens via httpOnly cookies or an OAuth/OIDC flow, protected routes, user context and token refresh, avoiding storing sensitive tokens in localStorage.'),
  (90, 1, 'Embedding the API secret key in the bundle so the frontend can sign and validate its own tokens.'),
  (90, 2, 'Store the username and password in localStorage, send them in the body of every API request and check the user''s permissions only in the frontend, since the backend trusts requests from the SPA.'),
  (90, 3, 'Storing the username and password in localStorage and sending them on every request.'),
  (91, 0, 'Semantic HTML, ARIA attributes, focus management, form labels, keyboard navigation and testing with axe/eslint-plugin-jsx-a11y.'),
  (91, 1, 'React handles accessibility automatically for every element, so no additional attributes, testing or focus handling are needed.'),
  (91, 2, 'Using only <div> elements with onClick handlers, since React normalizes them for screen readers and keyboards.'),
  (91, 3, 'Adding role="button" to every element to make it accessible.'),
  (92, 0, 'A Hook for safely subscribing to external data sources with concurrent rendering, avoiding "tearing". State libraries use it.'),
  (92, 1, 'A Hook that synchronizes component state across browser tabs using localStorage events.'),
  (92, 2, 'A Hook that keeps component state in sync with a remote database in real time over WebSockets.'),
  (92, 3, 'A Hook that forces external scripts to load synchronously.'),
  (93, 0, 'Differences between server and client HTML (dates, window, randomness). Avoid them with useEffect for client-only data or suppressHydrationWarning.'),
  (93, 1, 'Missing keys in lists rendered on the server; avoid them by always using the array index as the key.'),
  (93, 2, 'Network failures while downloading the JavaScript bundle, which leave the page without event handlers. Avoid them by retrying the download in a service worker and inlining the bundle in the HTML.'),
  (93, 3, 'Using too many components on a page; avoid them by splitting into more pages.'),
  (94, 0, 'Firing requests in parallel (Promise.all), fetching data at the route/server level, using prefetch and Suspense.'),
  (94, 1, 'Fetch data inside each nested child''s useEffect, one level after another, adding a fixed delay between requests so the server is never overloaded by parallel calls.'),
  (94, 2, 'Adding a delay between requests so the server is not overloaded.'),
  (94, 3, 'Combining all API endpoints into a single sequential call chain.'),
  (95, 0, 'Splitting the application into independent frontends per team, integrated via Module Federation, iframes or web components.'),
  (95, 1, 'A very small React app with fewer than ten components, deployed separately from the main backend.'),
  (95, 2, 'A very small React application with fewer than ten components, deployed separately from the backend; it is built by splitting one component into many tiny components inside the same bundle.'),
  (95, 3, 'A React component that renders only on mobile devices.'),
  (96, 0, 'When the computation is cheap or there are no memoized children; memoization has a cost and complexity and may be premature.'),
  (96, 1, 'When the component consumes Context, because memoization Hooks are incompatible with Providers.'),
  (96, 2, 'Never: they should wrap every value and function in every component, because memoization is free and the React team recommends it as the default to guarantee maximum performance.'),
  (96, 3, 'When the component is rendered on the server, since they throw errors there.'),
  (97, 0, 'It uses SyntheticEvents, attaching listeners at the app root (not on each node) and normalizing behavior across browsers.'),
  (97, 1, 'It attaches a native listener directly to each DOM node that has an onClick prop, removing it on unmount.'),
  (97, 2, 'It delegates all events to a Web Worker that processes them off the main thread and posts results back.'),
  (97, 3, 'It uses a polling loop to check for user input every frame.'),
  (98, 0, 'Pyramid: unit tests for hooks/utilities, component integration tests with RTL, network mocks with MSW and few E2E tests (Playwright/Cypress).'),
  (98, 1, 'Only snapshot tests of every component, since snapshots cover rendering and behavior completely.'),
  (98, 2, 'An inverted pyramid: mostly end-to-end tests through the UI for every feature with Selenium, plus snapshot tests of each component, and almost no unit or integration tests.'),
  (98, 3, 'Manual QA only, because automated tests slow down development.'),
  (99, 0, 'It lets compatible libraries suspend rendering while data loads, showing the nearest boundary''s fallback.'),
  (99, 1, 'It fetches data automatically for any component wrapped in it, without requiring a compatible library.'),
  (99, 2, 'It cancels data requests that take longer than the timeout prop and shows an error boundary instead.'),
  (99, 3, 'It caches all fetch calls globally for the session.'),
  (100, 0, 'Incrementally, converting leaf components first, extracting lifecycle logic into Hooks and keeping both coexisting.'),
  (100, 1, 'All at once in a single release, because class components and Hooks cannot coexist in the same application; an official codemod converts every class automatically without review.'),
  (100, 2, 'All at once, since classes and Hooks cannot coexist in the same app.'),
  (100, 3, 'By running an official codemod that converts everything automatically with no review.')
) as v (source_id, source_index, body)
join public.questions q on q.quiz_id = 'react' and q.language = 'en' and q.source_id = v.source_id
on conflict (question_id, source_index) do update set body = excluded.body, is_correct = excluded.is_correct;

