insert into public.answer_options (question_id, source_index, body, is_correct)
select q.id, v.source_index, v.body, v.source_index = 0
from (values
  (1, 0, 'Uma biblioteca JavaScript declarativa, baseada em componentes, criada pelo Facebook (Meta) para construir interfaces de usuário.'),
  (1, 1, 'Um framework full-stack criado pelo Google que reúne roteamento, motor de templates e ORM para construir aplicações web renderizadas no servidor.'),
  (1, 2, 'Uma biblioteca imperativa de manipulação do DOM criada pela Microsoft que substituiu o jQuery como forma padrão de atualizar páginas HTML diretamente.'),
  (1, 3, 'Um motor de templates imperativo criado pela Microsoft que compila arquivos HTML em bundles JavaScript otimizados.'),
  (2, 0, 'Uma extensão de sintaxe que permite escrever estruturas parecidas com HTML dentro do JavaScript. É transformada em chamadas React.createElement (ou jsx()) pelo compilador.'),
  (2, 1, 'Uma linguagem de templates que o navegador interpreta nativamente em runtime, convertendo tags em nós do DOM sem exigir Babel ou qualquer etapa de compilação.'),
  (2, 2, 'Um superconjunto estrito do HTML que o React envia ao servidor, onde é renderizado em markup estático e devolvido ao cliente como string.'),
  (2, 3, 'Uma nova linguagem de programação que substitui o JavaScript em projetos React e é executada diretamente pelo navegador sem compilação.'),
  (3, 0, 'Uma função (ou classe) reutilizável que recebe props e retorna elementos React descrevendo parte da UI.'),
  (3, 1, 'Um singleton global que armazena todo o estado da aplicação e é compartilhado automaticamente com todas as páginas pelo runtime do React.'),
  (3, 2, 'Um arquivo HTML carregado em runtime e injetado na página com innerHTML, descrevendo parte da interface como markup estático.'),
  (3, 3, 'Um módulo CSS que agrupa estilos e é aplicado aos elementos do DOM pelo nome da classe.'),
  (4, 0, 'Funcionais são funções simples que usam Hooks para estado e efeitos; os de classe usam this, state e métodos de ciclo de vida. Hoje o padrão é usar funcionais.'),
  (4, 1, 'Componentes de classe são funções simples que usam Hooks, enquanto os funcionais usam this, state e métodos de ciclo de vida; classes são o padrão moderno.'),
  (4, 2, 'Componentes funcionais não podem ter estado nem efeitos; componentes de classe são a única forma de gerenciar estado e são o padrão recomendado atualmente.'),
  (4, 3, 'Componentes de classe rodam no servidor e componentes funcionais rodam apenas no navegador; ambos são igualmente recomendados hoje.'),
  (5, 0, 'Dados passados do componente pai para o filho, somente leitura (imutáveis dentro do filho).'),
  (5, 1, 'Dados pertencentes ao componente filho, que ele pode modificar livremente e enviar de volta ao pai automaticamente a cada render.'),
  (5, 2, 'Variáveis globais injetadas pelo React em todos os componentes, acessíveis em qualquer lugar sem precisar ser repassadas explicitamente.'),
  (5, 3, 'Variáveis globais compartilhadas por todos os componentes da aplicação sem precisar ser repassadas.'),
  (6, 0, 'Dados internos de um componente que mudam ao longo do tempo e, ao serem alterados, provocam nova renderização.'),
  (6, 1, 'Dados somente leitura recebidos do componente pai que nunca mudam durante a vida do componente e nunca disparam renders.'),
  (6, 2, 'Dados armazenados no localStorage do navegador que o React lê automaticamente a cada renderização.'),
  (6, 3, 'Um objeto de configuração estático definido uma vez no build e compartilhado entre todas as instâncias do componente.'),
  (7, 0, 'Props vêm de fora e são imutáveis para o componente; state pertence ao componente e é atualizado por ele (via setState/useState).'),
  (7, 1, 'Props pertencem ao componente e podem ser alteradas diretamente; state vem do pai e é somente leitura.'),
  (7, 2, 'Props e state são a mesma coisa; os nomes são intercambiáveis e só diferem entre componentes de classe e funcionais.'),
  (7, 3, 'Props são usadas apenas para estilização, enquanto state é usado apenas para dados buscados de APIs.'),
  (8, 0, 'Uma representação em memória da árvore de elementos. O React compara versões (diffing) e aplica no DOM real só o que mudou.'),
  (8, 1, 'Uma cópia oculta do DOM real que o React descarta e recria por completo a cada render, substituindo a página inteira para se manter sincronizado.'),
  (8, 2, 'Uma API do navegador, semelhante ao Shadow DOM, que isola estilos e markup de cada componente do restante da página para encapsulamento.'),
  (8, 3, 'Um cache no servidor de páginas HTML renderizadas que o React entrega no lugar do DOM real para melhorar o SEO.'),
  (9, 0, 'Hook que declara uma variável de estado em componente funcional. Retorna [valor, setValor].'),
  (9, 1, 'Hook que retorna um objeto mutável cuja propriedade .current persiste entre renders sem causar nova renderização.'),
  (9, 2, 'Hook que lê um valor do Provider de Context mais próximo e o retorna junto com uma função dispatch.'),
  (9, 3, 'Hook que retorna um objeto mutável cuja propriedade .current persiste sem causar re-renderização.'),
  (10, 0, 'Hook para executar efeitos colaterais (requisições, assinaturas, manipulação do DOM) após a renderização, controlado por um array de dependências.'),
  (10, 1, 'Hook que roda de forma síncrona durante a renderização para calcular valores derivados antes de o JSX ser retornado, controlado por um array de dependências.'),
  (10, 2, 'Hook que memoriza um cálculo custoso e o recalcula apenas quando as dependências mudam.'),
  (10, 3, 'Hook que roda apenas uma vez no servidor para buscar dados antes de o HTML ser enviado ao cliente.'),
  (11, 0, 'Lista de valores que, ao mudarem, fazem o efeito rodar de novo. Array vazio roda só na montagem; sem array roda a cada renderização.'),
  (11, 1, 'Lista de valores que o efeito não pode ler. Array vazio faz o efeito rodar a cada renderização; omiti-lo faz rodar só na montagem.'),
  (11, 2, 'Lista de componentes filhos que devem re-renderizar após o efeito. Array vazio desativa o efeito completamente.'),
  (11, 3, 'Lista de props repassadas à função de limpeza. Omiti-lo faz o efeito rodar apenas na desmontagem.'),
  (12, 0, 'Com if, operador ternário (cond ? A : B), && (cond && <A/>) ou retornando null.'),
  (12, 1, 'Apenas com os componentes nativos <If>, <ElseIf> e <Else> que o React exporta, já que o JSX não avalia expressões JavaScript dentro das chaves.'),
  (12, 2, 'Com as diretivas v-if e v-show colocadas diretamente nos elementos JSX, que o React avalia antes de decidir o que renderizar.'),
  (12, 3, 'Definindo display: none pela prop hidden, já que o JSX não suporta expressões JavaScript.'),
  (13, 0, 'Usando array.map() retornando elementos, cada um com uma key única e estável.'),
  (13, 1, 'Usando array.forEach() dentro das chaves do JSX, que coleta os elementos retornados automaticamente e atribui keys pela posição.'),
  (13, 2, 'Usando o componente nativo <List items={...}>, que itera o array e gera keys estáveis, dispensando informá-las.'),
  (13, 3, 'Usando um laço for diretamente dentro das chaves do JSX, com o índice do array como única opção de key.'),
  (14, 0, 'Ajuda o React a identificar quais itens mudaram, foram adicionados ou removidos, otimizando a reconciliação.'),
  (14, 1, 'Define o seletor CSS que o React usa para estilizar cada item da lista, de modo que itens com a mesma key compartilham estilos.'),
  (14, 2, 'Define a ordem em que os itens são ordenados antes de renderizar, então o React sempre os exibe em ordem crescente de key.'),
  (14, 3, 'Criptografa os itens da lista para que não possam ser lidos do DOM por scripts de terceiros.'),
  (15, 0, 'Se a lista for reordenada, filtrada ou tiver inserções, o índice muda e pode causar bugs de estado e renders desnecessários. Prefira IDs estáveis.'),
  (15, 1, 'Porque o React lança erro de compilação sempre que um número é usado como key, então índices sempre precisam ser convertidos em string.'),
  (15, 2, 'Porque keys numéricas são sempre mais lentas de comparar que strings, causando lentidão perceptível mesmo em listas que nunca mudam de ordem.'),
  (15, 3, 'Porque o React recalcula os índices a cada render usando uma semente aleatória, então o mesmo item recebe uma key diferente a cada vez e seu nó do DOM é sempre recriado do zero.'),
