from (values
  (1, 0, 'A typed superset of JavaScript, developed by Microsoft, that compiles to plain JavaScript and catches errors at development time.'),
  (1, 1, 'A new runtime developed by Google that executes typed code directly in the browser, replacing JavaScript engines and catching errors only when the code runs in production.'),
  (1, 2, 'A subset of JavaScript that removes dynamic features to make code run faster in Node.js.'),
  (1, 3, 'A linter developed by Facebook that checks JavaScript code style at runtime.'),
  (2, 0, 'Early error detection, better autocomplete and refactoring, self-documenting code and safer maintenance in large projects.'),
  (2, 1, 'Faster runtime execution, because browsers read the type annotations and use them to optimize the generated machine code for every function in large projects.'),
  (2, 2, 'Faster runtime execution, since types are used by the browser to optimize code.'),
  (2, 3, 'Smaller bundle size, since TypeScript removes unused code automatically.'),
  (3, 0, 'string, number, boolean, null, undefined, symbol and bigint.'),
  (3, 1, 'string, number, boolean, object, array, function and tuple, which are all represented as primitive values at runtime.'),
  (3, 2, 'string, int, float, double, char, boolean and void, mirroring the primitive types available in Java and C#.'),
  (3, 3, 'string, number, boolean, any, unknown and never.'),
  (4, 0, 'It disables type checking for that value. It should be avoided because it removes TypeScript''s safety.'),
  (4, 1, 'A safe type for unknown values that requires narrowing before use.'),
  (4, 2, 'A type representing values that never occur.'),
  (4, 3, 'A type that accepts only primitive values, not objects.'),
  (5, 0, 'A safe type for unknown values: you must narrow it (type narrowing) before using it.'),
  (5, 1, 'A type that disables all checking for the value, allowing any operation without narrowing; it is just a newer alias for any introduced in TypeScript 3.'),
  (5, 2, 'A type automatically assigned to variables declared without an initial value, which cannot be reassigned after the first assignment is made.'),
  (5, 3, 'A type that disables all type checking, identical to any.'),
  (6, 0, 'any allows any operation without checking; unknown requires a type check before use.'),
  (6, 1, 'unknown allows any operation without checking; any requires a type check before use.'),
  (6, 2, 'any is only for objects and unknown is only for primitives.'),
  (6, 3, 'There is no difference; unknown is an alias of any introduced in TS 3.'),
  (7, 0, 'It represents values that never occur, such as functions that always throw or impossible branches in exhaustive checks.'),
  (7, 1, 'It represents a function that returns nothing useful, like void.'),
  (7, 2, 'It represents null and undefined combined.'),
  (7, 3, 'It represents a variable that can never be reassigned, like const.'),
  (8, 0, 'It indicates that a function doesn''t return a useful value.'),
  (8, 1, 'It indicates a value that can never occur, such as the result of an infinite loop or a function that always throws.'),
