  (9, 3, 'array<string> or [string]...'),
  (10, 0, 'Arrays with a fixed length and fixed types per position, such as [string, number].'),
  (10, 1, 'Objects with exactly two properties named first and second, used to return pairs of values from functions without creating a class.'),
  (10, 2, 'Arrays that can grow to any length but can only contain values of a single type, such as number[] or string[].'),
  (10, 3, 'Immutable sets of unique values, like Set.'),
  (11, 0, 'A declaration that describes the shape of an object (properties and methods), which can be extended and implemented by classes.'),
  (11, 1, 'A runtime object that validates the data passed to functions and throws an error when a required property is missing or has the wrong type.'),
  (11, 2, 'A class that contains default implementations of methods, which other classes inherit by extending it with the implements keyword.'),
  (11, 3, 'A type that can only describe unions and primitives.'),
  (12, 0, 'A name for any type, created with type, including unions, intersections, tuples and primitives.'),
  (12, 1, 'A name for object shapes only, created with type, which supports declaration merging just like interfaces do.'),
  (12, 2, 'A runtime variable that stores a type so it can be inspected later through reflection APIs.'),
