on conflict (question_id, source_index) do update set body = excluded.body, is_correct = excluded.is_correct;

-- Achievements
insert into public.achievements (slug, name, description, icon, category, rarity, criteria_type, criteria_config, sort_order, is_active) values
  ('first-steps', 'First Steps', 'Complete your first official quiz.', 'footprints', 'completion', 'common', 'quizzes_completed', '{"count":1}'::jsonb, 10, true),
  ('quiz-explorer', 'Quiz Explorer', 'Complete 5 official quiz attempts.', 'compass', 'completion', 'common', 'quizzes_completed', '{"count":5}'::jsonb, 20, true),
  ('dedicated-learner', 'Dedicated Learner', 'Complete 10 official quiz attempts.', 'book-open-check', 'completion', 'uncommon', 'quizzes_completed', '{"count":10}'::jsonb, 30, true),
  ('quiz-master', 'Quiz Master', 'Complete 25 official quiz attempts.', 'crown', 'completion', 'epic', 'quizzes_completed', '{"count":25}'::jsonb, 40, true),
  ('full-marks', 'Full Marks', 'Complete an official quiz answering every question correctly on the first try.', 'badge-check', 'accuracy', 'uncommon', 'quiz_accuracy', '{"min_accuracy":100,"min_questions":1}'::jsonb, 50, true),
  ('level-complete-foundations', 'Level Complete', 'Complete a Basic-level attempt of the JavaScript, TypeScript and React quizzes.', 'layers', 'exploration', 'rare', 'level_completed', '{"level":"basic","quiz_ids":["javascript","typescript","react"]}'::jsonb, 60, true),
  ('react-specialist', 'Quiz Specialist', 'Complete the React quiz.', 'atom', 'exploration', 'common', 'quiz_completed', '{"quiz_id":"react"}'::jsonb, 70, true),
  ('sharp-mind', 'Sharp Mind', 'Answer 5 questions correctly in a row.', 'zap', 'streak', 'common', 'correct_streak', '{"count":5}'::jsonb, 80, true),
  ('focused-learner', 'Focused Learner', 'Answer 10 questions correctly in a row.', 'flame', 'streak', 'uncommon', 'correct_streak', '{"count":10}'::jsonb, 90, true),
  ('unstoppable', 'Unstoppable', 'Answer 50 questions correctly in a row.', 'rocket', 'streak', 'legendary', 'correct_streak', '{"count":50}'::jsonb, 100, true),
  ('curious-mind', 'Curious Mind', 'Answer 5 official questions correctly.', 'lightbulb', 'milestone', 'common', 'correct_answers', '{"count":5}'::jsonb, 110, true),
  ('knowledge-seeker', 'Knowledge Seeker', 'Answer 10 official questions correctly.', 'search', 'milestone', 'common', 'correct_answers', '{"count":10}'::jsonb, 120, true),
  ('knowledge-builder', 'Knowledge Builder', 'Answer 50 official questions correctly.', 'blocks', 'milestone', 'uncommon', 'correct_answers', '{"count":50}'::jsonb, 130, true),
  ('scholar', 'Scholar', 'Answer 100 official questions correctly.', 'graduation-cap', 'milestone', 'rare', 'correct_answers', '{"count":100}'::jsonb, 140, true),
  ('expert', 'Expert', 'Answer 500 official questions correctly.', 'trophy', 'milestone', 'legendary', 'correct_answers', '{"count":500}'::jsonb, 150, true),
  ('getting-the-hang-of-it', 'Getting the Hang of It', 'Reach at least 80% accuracy on a completed official quiz of 10 or more questions.', 'target', 'accuracy', 'common', 'quiz_accuracy', '{"min_accuracy":80,"min_questions":10}'::jsonb, 160, true),
  ('precision', 'Precision', 'Reach 100% accuracy on a completed official quiz of 10 or more questions.', 'crosshair', 'accuracy', 'rare', 'quiz_accuracy', '{"min_accuracy":100,"min_questions":10}'::jsonb, 170, true),
  ('first-try-champion', 'First-Try Champion', 'Answer 10 official questions correctly on the first try.', 'medal', 'accuracy', 'uncommon', 'first_try_correct', '{"count":10}'::jsonb, 180, true)
on conflict (slug) do update set name = excluded.name, description = excluded.description, icon = excluded.icon, category = excluded.category, rarity = excluded.rarity, criteria_type = excluded.criteria_type, criteria_config = excluded.criteria_config, sort_order = excluded.sort_order, is_active = excluded.is_active, updated_at = now();
update public.achievements set is_active = false, updated_at = now() where slug not in ('first-steps', 'quiz-explorer', 'dedicated-learner', 'quiz-master', 'full-marks', 'level-complete-foundations', 'react-specialist', 'sharp-mind', 'focused-learner', 'unstoppable', 'curious-mind', 'knowledge-seeker', 'knowledge-builder', 'scholar', 'expert', 'getting-the-hang-of-it', 'precision', 'first-try-champion');

commit;
